#if UNITY_EDITOR || DEVELOPMENT_BUILD
using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;
public sealed class PalaceContourCapture:MonoBehaviour
{
    string output;int checks;
    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Boot(){if(!Environment.GetCommandLineArgs().Contains("-palace-contour-capture"))return;Application.runInBackground=true;var dir=Path.GetFullPath(Path.Combine(Application.dataPath,"../Captures/PalaceContours"));Directory.CreateDirectory(dir);SaveGames.TestRoot=Path.Combine(dir,"Saves");Directory.CreateDirectory(SaveGames.TestRoot);VariableSingleton.TestSavePath=Path.Combine(SaveGames.TestRoot,"checkpoint.besieged.json");var go=new GameObject("Palace contour verification");DontDestroyOnLoad(go);go.AddComponent<PalaceContourCapture>().output=dir;}
    void Check(bool ok,string text){if(!ok)throw new Exception(text);checks++;}
    IEnumerator Start(){var work=new Stack<IEnumerator>();work.Push(Run());while(work.Count>0){object next=null;bool more=false;try{more=work.Peek().MoveNext();if(more)next=work.Peek().Current;}catch(Exception ex){File.WriteAllText(Path.Combine(output,"checks.txt"),"FAILED "+checks+"\n"+ex);Application.Quit(1);yield break;}if(!more){work.Pop();continue;}if(next is IEnumerator inner)work.Push(inner);else yield return next;}File.WriteAllText(Path.Combine(output,"checks.txt"),checks+" checks passed");Application.Quit(0);}
    LocationHotspot Find(string name)=>FindObjectsOfType<LocationHotspot>().Single(h=>h.name=="Hotspot · "+name);
    PointerEventData Point(RectTransform r,Vector2 uv){var area=r.rect;var world=r.TransformPoint(new Vector3(area.xMin+uv.x*area.width,area.yMin+uv.y*area.height));return new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(null,world),button=PointerEventData.InputButton.Left};}
    void Hit(LocationHotspot h,Vector2 inside,Vector2 outside){Check(h.Shape.Length>8,"detailed contour "+h.name);Check(h.Contains(inside)&&!h.Contains(outside),"silhouette interior and exterior "+h.name);Check(h.IsRaycastLocationValid(Point(h.rectTransform,inside).position,null),"scaled interior raycast "+h.name);Check(!h.IsRaycastLocationValid(Point(h.rectTransform,outside).position,null),"scaled exterior excluded "+h.name);h.SetHighlighted(true);}
    IEnumerator Run(){AudioListener.volume=0;yield return null;SaveMenu.StartCampaign(false);float until=Time.realtimeSinceStartup+30;while(!VariableSingleton.IsInitialized&&Time.realtimeSinceStartup<until)yield return null;Check(VariableSingleton.IsInitialized,"campaign initialized");yield return new WaitForSecondsRealtime(.4f);CampaignHUD.Instance.DismissReport();var council=CouncilUI.For(FindObjectOfType<ManagerUI>());ChurchCourt.Initialize();
        var art=PalaceFigureArt.Get(203);Check(art!=null&&art.texture.isReadable,"Gennadios full sprite loaded and readable");Check(art.texture.GetPixelBilinear(.1f,.5f).a<.01f,"transparent exterior");Check(CharacterPortraits.Texture(203)!=null,"matching portrait lookup");
        foreach(int width in new[]{1280,1600}){Screen.SetResolution(width,width==1280?720:900,false);yield return new WaitForSecondsRealtime(1.5f);council.Garden();yield return null;Canvas.ForceUpdateCanvases();var garden=Find("Return to the Palace");Hit(garden,new Vector2(.06f,.60f),new Vector2(.025f,.76f));yield return Capture(width+"-garden-door");garden.OnPointerClick(Point(garden.rectTransform,new Vector2(.06f,.60f)));yield return null;Check(GameObject.Find("Hotspot · The Emperor's chamber")!=null,"garden portal opens Palace");var chamber=Find("The Emperor's chamber");Hit(chamber,new Vector2(.07f,.50f),new Vector2(.028f,.70f));yield return Capture(width+"-palace-door");chamber.OnPointerClick(Point(chamber.rectTransform,new Vector2(.07f,.50f)));yield return null;Check(GameObject.Find("Private chamber painting")!=null,"palace portal opens chamber");var back=Find("Return to the Palace");Hit(back,new Vector2(.095f,.50f),new Vector2(.20f,.80f));yield return Capture(width+"-chamber-door");back.OnPointerClick(Point(back.rectTransform,new Vector2(.095f,.50f)));yield return null;
            var ships=FindObjectsOfType<LocationHotspot>().Where(h=>h.name=="Hotspot · Fleet orders").ToArray();Check(ships.Length==3&&ships.All(s=>s.OutlinePeers.Length==3&&s.Shape.Length>=10),"three linked ship silhouettes");foreach(var s in ships)s.SetHighlighted(true);yield return Capture(width+"-fleet-ships");ships[0].Action.Invoke();yield return null;Check(GameObject.Find("Hotspot · The Emperor's chamber")==null,"ships navigate away to Fleet");
            VariableSingleton.SetInt("iLifeLocationTurn",VariableSingleton.Turn+1);VariableSingleton.SetInt("iLifeLocationVisitor2",203);council.HagiaSophia();yield return null;Canvas.ForceUpdateCanvases();var figure=GameObject.Find("Palace court figure 203");Check(figure!=null,"Gennadios appears in assigned room");var image=figure.GetComponent<CourtSilhouetteImage>();foreach(var p in new[]{new Vector2(.55f,.90f),new Vector2(.52f,.64f),new Vector2(.30f,.025f)})Check(image.IsRaycastLocationValid(Point(image.rectTransform,p).position,null),"Gennadios head torso shoe clickable");Check(!image.IsRaycastLocationValid(Point(image.rectTransform,new Vector2(.02f,.90f)).position,null),"sprite transparent corner excluded");yield return Capture(width+"-gennadios");
        }
    }
    IEnumerator Capture(string name){yield return null;Canvas.ForceUpdateCanvases();var go=new GameObject("Capture camera",typeof(Camera));var camera=go.GetComponent<Camera>();camera.orthographic=true;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=Color.black;camera.nearClipPlane=.1f;camera.farClipPlane=100;var canvases=FindObjectsOfType<Canvas>().Where(c=>c.isRootCanvas).ToArray();var modes=canvases.Select(c=>c.renderMode).ToArray();var cams=canvases.Select(c=>c.worldCamera).ToArray();var distances=canvases.Select(c=>c.planeDistance).ToArray();var target=RenderTexture.GetTemporary(Screen.width,Screen.height,24);var prior=RenderTexture.active;Texture2D shot=null;try{camera.targetTexture=target;foreach(var c in canvases){c.renderMode=RenderMode.ScreenSpaceCamera;c.worldCamera=camera;c.planeDistance=10;}Canvas.ForceUpdateCanvases();camera.Render();RenderTexture.active=target;shot=new Texture2D(target.width,target.height,TextureFormat.RGB24,false);shot.ReadPixels(new Rect(0,0,target.width,target.height),0,0);shot.Apply();File.WriteAllBytes(Path.Combine(output,name+".png"),shot.EncodeToPNG());}finally{RenderTexture.active=prior;for(int i=0;i<canvases.Length;i++){canvases[i].renderMode=modes[i];canvases[i].worldCamera=cams[i];canvases[i].planeDistance=distances[i];}camera.targetTexture=null;RenderTexture.ReleaseTemporary(target);if(shot!=null)Destroy(shot);Destroy(go);}}
}
#endif
